#include "CaptureStorage.h"
#include <LittleFS.h>
#include <ArduinoJson.h>
#include <algorithm>
static uint32_t crc32(const uint8_t* p,size_t n){uint32_t c=~0u;for(size_t i=0;i<n;i++){c^=p[i];for(int k=0;k<8;k++)c=(c>>1)^((c&1)?0xedb88320u:0);}return ~c;}
struct Header{uint32_t magic,length,crc,metaLength;};
String CaptureStorage::path(const String& id) const{return "/q/"+id+".rec";}
bool CaptureStorage::begin(){if(!LittleFS.begin(true))return false;LittleFS.mkdir("/q");File d=LittleFS.open("/q");File f=d.openNextFile();while(f){String name=f.name();if(name.endsWith(".tmp"))LittleFS.remove(name);f=d.openNextFile();}return true;}
size_t CaptureStorage::freeBytes(){return LittleFS.totalBytes()-LittleFS.usedBytes();}
bool CaptureStorage::append(const CaptureRecord& r,const uint8_t* data,size_t n){if(n>65536||n+2048>freeBytes()){lost_++;return false;}JsonDocument j;j["id"]=r.id;j["ip"]=r.ip;j["port"]=r.port;j["timestamp"]=r.timestamp;j["format"]=r.format;j["text"]=r.text;j["uploaded"]=false;String meta;serializeJson(j,meta);Header h{0x574f4e47,(uint32_t)n,crc32(data,n),(uint32_t)meta.length()};String tmp=path(r.id)+".tmp";File f=LittleFS.open(tmp,"w");if(!f){lost_++;return false;}bool ok=f.write((uint8_t*)&h,sizeof h)==sizeof h && f.write((uint8_t*)meta.c_str(),meta.length())==meta.length() && f.write(data,n)==n;f.flush();f.close();if(!ok||!LittleFS.rename(tmp,path(r.id))){LittleFS.remove(tmp);lost_++;return false;}return true;}
bool CaptureStorage::readMeta(const String& id,CaptureRecord& r){File f=LittleFS.open(path(id),"r");Header h;if(!f||f.readBytes((char*)&h,sizeof h)!=sizeof h||h.magic!=0x574f4e47||h.length>65536||h.metaLength>2048)return false;String m;for(uint32_t i=0;i<h.metaLength;i++)m+=(char)f.read();std::vector<uint8_t> b(h.length);if(f.read(b.data(),b.size())!=b.size()||crc32(b.data(),b.size())!=h.crc)return false;JsonDocument j;if(deserializeJson(j,m))return false;r.id=j["id"].as<String>();r.ip=j["ip"].as<String>();r.port=j["port"]|0;r.timestamp=j["timestamp"].as<uint64_t>();r.format=j["format"].as<String>();r.text=j["text"].as<String>();r.bytes=h.length;return true;}
std::vector<CaptureRecord> CaptureStorage::history(size_t limit){std::vector<CaptureRecord> v;File d=LittleFS.open("/q");File f=d.openNextFile();while(f){String name=f.name();int slash=name.lastIndexOf('/');name=name.substring(slash+1);if(name.endsWith(".rec")){CaptureRecord r;if(readMeta(name.substring(0,name.length()-4),r))v.push_back(r);}f=d.openNextFile();}std::sort(v.begin(),v.end(),[](auto&a,auto&b){return a.timestamp>b.timestamp;});if(v.size()>limit)v.resize(limit);return v;}
bool CaptureStorage::raw(const String& id,std::vector<uint8_t>& out){File f=LittleFS.open(path(id),"r");Header h;if(!f||f.readBytes((char*)&h,sizeof h)!=sizeof h||h.magic!=0x574f4e47||h.length>65536||h.metaLength>2048)return false;f.seek(sizeof h+h.metaLength);out.resize(h.length);return f.read(out.data(),out.size())==out.size()&&crc32(out.data(),out.size())==h.crc;}
bool CaptureStorage::acknowledge(const String& id){CaptureRecord r;if(!readMeta(id,r))return false;return LittleFS.remove(path(id));}
size_t CaptureStorage::pending(){return history(100000).size();}
